selector_to_html = {"a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.ducts.manifold_law\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.manifold_law<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.manifold_law\" title=\"Link to this heading\">\u00b6</a></h1><p>Rules that set how a manifold\u2019s passage grows as it gathers flow.</p><p>A volute\u2019s area law answers to swirl: the passage is sized so the angular\nmomentum it collects is conserved, and departing from that is what costs the\ntangential loss. A chamber manifold has no swirl to conserve. Its circumferential\nvelocity is a nuisance rather than a design variable \u2013 it exists only because\nfluid has to travel round to reach the far channels \u2013 so the laws here answer a\ndifferent question: how much dynamic head does the passage carry, and is it the\nsame everywhere the channels tap into it?</p>", "a[href=\"ConstantVelocity.html#pyskyfire.ducts.manifold_law.ConstantVelocity.for_duty\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold_law.ConstantVelocity.for_duty\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">for_duty</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">velocity</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">density</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Size the law from a duty and the velocity it should be carried at.</p></dd>", "a[href=\"ManifoldLaw.html#pyskyfire.ducts.manifold_law.ManifoldLaw\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold_law.ManifoldLaw\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ManifoldLaw</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>A rule relating flow gathered to passage size.</p></dd>", "a[href=\"../area_law/ConstantArea.html#pyskyfire.ducts.area_law.ConstantArea\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.area_law.ConstantArea\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.area_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ConstantArea</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">AreaLaw</span></code></p><p>Hold the passage area uniform all the way around.</p><p>This is Aungier\u2019s \u201ccollector\u201d rather than a volute. It collects the flow\nwithout conserving angular momentum, so its sizing parameter is whatever\nthe chosen area happens to produce and its tangential-velocity loss is\ncorrespondingly larger. Aungier\u2019s Eq. 5-108 additionally averages that loss\nagainst a total loss of tangential head, because a uniform passage tries to\ndiffuse the entering flow to rest where collection begins.</p></dd>", "a[href=\"UniformArea.html#pyskyfire.ducts.manifold_law.UniformArea\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold_law.UniformArea\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">UniformArea</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ManifoldLaw</span></code></p><p>Hold the passage area constant all the way round.</p><p>The plain toroidal manifold. It carries more dynamic head near the port\nthan at the dead point, since the same area passes a growing share of the\nflow, so it relies on being oversized enough that the variation does not\nreach the channels. That is the usual rule for a coolant manifold, and it\nis why the parameter here is simply the area the designer chose.</p></dd>", "a[href=\"ConstantVelocity.html#pyskyfire.ducts.manifold_law.ConstantVelocity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold_law.ConstantVelocity\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold_law.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ConstantVelocity</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">ManifoldLaw</span></code></p><p>Grow the passage in step with the flow it has gathered.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">A</span> <span class=\"pre\">=</span> <span class=\"pre\">collected</span> <span class=\"pre\">*</span> <span class=\"pre\">full_area</span></code> holds the through-flow velocity uniform, and\nwith it the dynamic head, so every branch tapping the manifold sees the\nsame static pressure. That evenness is the point; the velocity is how it is\nobtained.</p><p>The area goes to zero at the dead point, which no section family can build.\nStations where the law asks for less than the smallest section are flagged\nthrough <code class=\"docutils literal notranslate\"><span class=\"pre\">geometry.clipped</span></code>, exactly as a volute\u2019s tongue is.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
